+    DECOMPOSE_OP(==, std::cmp_equal)
+    DECOMPOSE_OP(!=, std::cmp_not_equal)
+    DECOMPOSE_OP(<, std::cmp_less)
+    DECOMPOSE_OP(<=, std::cmp_less_equal)
+    DECOMPOSE_OP(>, std::cmp_greater)
